mapper.select:
SELECT cm.id, cm.chat_room_id, cm.sender_id, u.nickname AS sender_nickname, cm.message_type, cm.message, cm.parent_message_id, cm.file_group_id, cm.status, cm.edited_at, cm.sent_at, cm.deleted_at, cm.created_at, cm.updated_at FROM chat_message cm INNER JOIN users u ON cm.sender_id = u.id WHERE cm.chat_room_id = #{chatRoomId} AND cm.deleted_at IS NULL AND cm.status = 'NORMAL'
AND id < #{cursor}
ORDER BY id DESC LIMIT #{size}

SELECT cm.id, cm.chat_room_id, cm.sender_id, cm.message_type, cm.message, cm.status, cm.sent_at FROM chat_message cm INNER JOIN ( SELECT chat_room_id, MAX(id) AS max_id FROM chat_message WHERE deleted_at IS NULL AND status = 'NORMAL' AND chat_room_id IN
#{roomId}
GROUP BY chat_room_id ) latest ON cm.id = latest.max_id
